/// Specification function (pure, mathematical definition):
///
/// Defines the triangular number of n inductively on natural numbers.
///
/// triangle(0) = 0
/// triangle(n) = n + triangle(n - 1) for n > 0
fn triangle(n: u32) -> u32 {
    if n == 0 {
        0
    } else {
        n + triangle(n - 1)
    }
}

/// Proof function (informal in Rust):
///
/// Proves that the triangular function is monotonic:
/// For all i, j with i <= j, triangle(i) <= triangle(j).
///
/// Intuitively, since triangle sums 1 to n,
/// if i <= j, triangle(i) sums fewer or equal positive terms,
/// so triangle(i) <= triangle(j).
///
/// This is expressed here by a simple runtime check for demonstration,
/// but formally it is a mathematical induction proof.
fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    if i <= j {
        triangle(i) <= triangle(j)
    } else {
        // If i > j, monotonicity condition doesn't apply
        true
    }
}

/// Tail-recursive procedure to compute triangle(n) by incrementally
/// updating sum from index idx up to n.
///
/// Assumptions / Preconditions:
/// - idx <= n
/// - sum initially holds triangle(idx)
/// - triangle(n) fits within u32 (no overflow)
///
/// This function updates *sum in-place to triangle(n).
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // measure for recursion: n - idx (strictly decreases every recursion)
    if idx == n {
        // base case: already at target, sum holds triangle(n)
        return;
    } else {
        // increment idx by 1
        let next_idx = idx + 1;
        // add next_idx to accumulator
        *sum += next_idx;
        // recursively continue towards n
        tail_triangle(n, next_idx, sum);
    }
}

